// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _test(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        uint256 userBalBefore;
        try c.balances(address(this)) returns (uint256 __r) { userBalBefore = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint balAfter = address(c).balance;
        uint256 userBalAfter;
        try c.balances(address(this)) returns (uint256 __r) { userBalAfter = __r; } catch { return; }
        assertTrue(balAfter - balBefore == userBalAfter - userBalBefore);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }

    receive() external payable {}
}
